TRIGGERED_ABILITY.RESOLUTION_TIME_ACTION:
local num_starting_players = MTG():GetNumberOfStartingPlayers() for i=0,(num_starting_players-1) do local player = MTG():GetNthStartingPlayer(i)
if (player ~= nil and player:GetTeam() ~= EffectController():GetTeam()) then local interrogation = MTG():ClearInterrogationQuery() interrogation:SetSecondaryPlayer(player)
if interrogation:Test( INTERROGATE_DAMAGE_DEALT, INTERROGATE_THIS_TURN ) then --bloodthirst! EffectSource():AddCounters( MTG():PlusOnePlusOneCounters(), 2 ) return end end end
